package ru.neverland.townypolicies.data;
import java.nio.file.*;
import java.nio.channels.FileChannel;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
import java.util.*;
import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.townypolicies.model.*;
import static ru.neverland.townypolicies.config.PoliciesSettings.integer;
public final class PoliciesRepository {
    private final Path file;private boolean writable;private final ru.neverland.core.AcknowledgedState<Map<UUID,CityPolicies>> storage;
    public PoliciesRepository(Path file){this.file=file;storage=new ru.neverland.core.AcknowledgedState<>(file,Map.of(),PoliciesRepository::encode,"NeverLand-policies-write");}public CityPolicies get(UUID town){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {return storage.get().getOrDefault(town,CityPolicies.empty());} }public Map<UUID,CityPolicies> towns(){ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {return storage.get();} }
    public void load()throws Exception{ try (var suiteGuard3 = ru.neverland.core.SuiteState.guard()) {writable=false;if(!Files.exists(file)){storage.loaded(Map.of());writable=true;return;}var y=new YamlConfiguration();y.load(file.toFile());if(integer(y.get("schema"))!=1||!y.isConfigurationSection("towns"))throw new IOException("Неверная схема policies-data.yml");var next=new HashMap<UUID,CityPolicies>();var root=y.getConfigurationSection("towns");for(String id:root.getKeys(false)){var t=root.getConfigurationSection(id);if(t==null||!t.isConfigurationSection("choices")||!t.isConfigurationSection("history"))throw new IOException("Неверная запись города");var choices=new HashMap<String,CityPolicies.Choice>();var c=t.getConfigurationSection("choices");for(String group:c.getKeys(false)){var v=c.getConfigurationSection(group);if(v==null)throw new IOException("Неверный выбор");choices.put(group,new CityPolicies.Choice(v.getString("mode"),integer(v.get("at")),integer(v.get("next"))));}var history=new ArrayList<CityPolicies.Change>();var h=t.getConfigurationSection("history");for(String key:h.getKeys(false)){var v=h.getConfigurationSection(key);if(v==null)throw new IOException("Неверная история");history.add(new CityPolicies.Change(integer(v.get("at")),v.getString("group"),v.getString("before"),v.getString("after"),UUID.fromString(v.getString("actor")),v.getString("actor-name")));}next.put(UUID.fromString(id),new CityPolicies(integer(t.get("revision")),choices,history));}storage.loaded(Map.copyOf(next));writable=true;} }
    public boolean busy(){return storage.busy();}
    public java.util.concurrent.CompletionStage<Void> putAsync(UUID town,CityPolicies state){try(var guard=ru.neverland.core.SuiteState.guard()){var next=new HashMap<>(storage.get());next.put(town,state);return replaceAsync(next);}}
    public java.util.concurrent.CompletionStage<Void> replaceAsync(Map<UUID,CityPolicies> next){try(var guard=ru.neverland.core.SuiteState.guard()){if(!writable)return java.util.concurrent.CompletableFuture.failedFuture(new IOException("База политик не загружена; запись запрещена"));return storage.commit(storage.get(),Map.copyOf(next)).thenApply(v->null);}}
    /** Offline compatibility helper; server commands must use putAsync. */
    public void put(UUID town,CityPolicies state)throws IOException{if(ru.neverland.core.SuiteState.held())throw new IllegalStateException("Нельзя ждать запись под общей блокировкой");var next=new HashMap<>(towns());next.put(town,state);replace(next);}
    public void replace(Map<UUID,CityPolicies> next)throws IOException{if(ru.neverland.core.SuiteState.held())throw new IllegalStateException("Нельзя ждать запись под общей блокировкой");try{replaceAsync(next).toCompletableFuture().join();}catch(java.util.concurrent.CompletionException error){throw new IOException("Указ не подтверждён",error.getCause());}}
    public java.util.concurrent.CompletionStage<Void> prepareClose(){return storage.prepareClose();}public void awaitClosed(){storage.awaitClosed();}
    private static String encode(Map<UUID,CityPolicies> next){var y=new YamlConfiguration();y.set("schema",1);y.createSection("towns");for(var row:next.entrySet()){String k="towns."+row.getKey()+".";var state=row.getValue();y.set(k+"revision",state.revision());y.createSection(k+"choices");y.createSection(k+"history");state.choices().forEach((group,c)->{String p=k+"choices."+group+".";y.set(p+"mode",c.mode());y.set(p+"at",c.chosenAt());y.set(p+"next",c.nextChangeAt());});for(int i=0;i<state.history().size();i++){var h=state.history().get(i);String p=k+"history."+i+".";y.set(p+"at",h.at());y.set(p+"group",h.group());y.set(p+"before",h.before());y.set(p+"after",h.after());y.set(p+"actor",h.actor().toString());y.set(p+"actor-name",h.actorName());}}return y.saveToString();}
}
